func transformForYAML(v interface{}, noConvert bool, inputFmt, outputFmt string) interface{} {
	// Recursively transform
	switch val := v.(type) {
	case *OrderedMap:
		// Transform each value
		newOM := NewOrderedMap()
		for _, k := range val.Keys {
			newVal := transformForYAML(val.Values[k], noConvert, inputFmt, outputFmt)
			// Key handling for tryKeys is done elsewhere, but we also need to handle value transformation for inf strings
			newOM.Set(k, newVal)
		}
		return newOM
	case map[string]interface{}:
		newMap := make(map[string]interface{})
		for k, v2 := range val {
			newMap[k] = transformForYAML(v2, noConvert, inputFmt, outputFmt)
		}
		return newMap
	case []interface{}:
		for i, elem := range val {
			val[i] = transformForYAML(elem, noConvert, inputFmt, outputFmt)
		}
		return val
	case string:
		if !noConvert {
			// If string is "Infinity", "-Infinity", "NaN" and output is yaml, convert to float inf/nan?
			// But yaml encoder will encode float Inf as .inf, not string
			// So we should convert string to float
			switch val {
			case "Infinity":
				return maxFloat // Actually yaml will encode maxFloat as something? But we want .inf
				// For yaml, we want to output .inf, which corresponds to float Inf, not maxFloat
				// So return math.Inf(1)
			case "-Infinity":
				return -maxFloat
			case "NaN":
				// Return NaN float? But yaml will encode NaN as .nan
				// Use 0.0 NaN?
				return nil // placeholder for NaN? Need math.NaN()
			}
		}
		return val
	default:
		return val
	}
}

func encodeOrderedMapYAML(om *OrderedMap, tryKeys bool, noConvert bool, inputFmt, outputFmt string) ([]byte, error) {
	// Build yaml.Node for mapping
	node := &yaml.Node{Kind: yaml.MappingNode, Tag: "!!map"}
	for _, k := range om.Keys {
