		var keyNode *yaml.Node
		if tryKeys {
			// Try to parse key as yaml value
			parsedKey, isComplex := parseKeyAsYAML(k)
			if isComplex {
				// Complex key: need to encode as explicit key with ? 
				// For now, create node for parsedKey
				keyNode = valueToYAMLNode(parsedKey, noConvert, inputFmt, outputFmt)
				// Mark as complex? yaml.Node for complex key handling is via explicit?
				// The yaml encoder will handle complex keys via "?" syntax if key node is not scalar?
				// For "[1,2]" with -k, parsedKey is []interface{}{1,2}, valueToYAMLNode will give SequenceNode, which when used as key will be encoded with ?
			} else {
