				if parsedKey == nil {
					// For "null" key with -k, parsedKey is nil, encoding will fail? Original gave error
					// We should return error to trigger "Error writing YAML"
					return nil, fmt.Errorf("reflect: call of reflect.Value.Set on zero Value")
				}
				// Use parsed key's string representation? But we need to create node
				keyNode = valueToYAMLNode(parsedKey, noConvert, inputFmt, outputFmt)
				// For numeric and bool keys, the node will be scalar with appropriate tag, and yaml will encode without quotes
			}
			// If not tryKeys, keyNode is string scalar
			if !tryKeys {
				keyNode = &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!str", Value: k, Style: yaml.DoubleQuotedStyle}
				// But need to decide style: For string keys without special chars, plain style is used.
				// Our earlier observed: json {"a":1} -> yaml "a: 1\n" (plain), not quoted. For {"1": "a"} without k -> "\"1\": a\n" (double quoted). With k -> "1: a\n" (plain). So quoting depends.
				// Use plain style and let yaml handle?
			}
		} else {
			// Not tryKeys: key is string, but need to handle quoting: If key needs quoting, yaml will quote
			// We'll create scalar node with Value=k and let encoder decide style
			// For numeric string "1" without k, we want quoted "1", so we need to force double quoted?
			// The yaml encoder will by default quote numeric-looking strings? Let's see
			// For key "1", we want output "\"1\": a" without k, so need quoted style
			// For key "a", we want "a: 1" plain
			// How to decide? We can check if k looks like number/bool/null, then we want quoted
			// Otherwise plain
			// We'll use DoubleQuotedStyle for keys that would be interpreted as non-string if plain
			if isYAMLPlainScalar(k) {
				keyNode = &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!str", Value: k}
			} else {
				// Need quoted to preserve string type
				// Check if k is numeric, bool, null etc.
				keyNode = &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!str", Value: k, Style: yaml.DoubleQuotedStyle}
				// For "1", this will produce "\"1\""
				// But we need to ensure style is double quoted, not plain
			}
			// Actually simpler: always use String style and let yaml decide? But yaml will output "1" as plain "1" which would be parsed as int, not string. So we need to force quotes.
			// So we need to detect if plain would be misinterpreted, then use quoted
		}
		// For tryKeys case, we already have keyNode
		if tryKeys {
			// Already handled
		} else {
			// Recreate with correct logic
			if k == "true" || k == "false" || k == "null" || isNumeric(k) {
				keyNode = &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!str", Value: k, Style: yaml.DoubleQuotedStyle}
			} else {
				// Check if key contains special chars like ":" or " " that still can be plain? For "a b", plain is "a b: 1" which is allowed as plain? Observed "a b: 1" without quotes. So plain.
				keyNode = &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!str", Value: k}
			}
		}
		valNode := valueToYAMLNode(om.Values[k], noConvert, inputFmt, outputFmt)
		node.Content = append(node.Content, keyNode, valNode)
	}
	var buf bytes.Buffer
	enc := yaml.NewEncoder(&buf)
	enc.SetIndent(2)
	if err := enc.Encode(node); err != nil {
		return nil, err
	}
	enc.Close()
	return buf.Bytes(), nil
}

func isYAMLPlainScalar(s string) bool {
	// Check if s can be plain scalar without being interpreted as other type
	// For now, return true if s is simple identifier
	return false
}
func isNumeric(s string) bool {
	_, err1 := strconv.ParseInt(s, 10, 64)
	if err1 == nil {
		return true
	}
	_, err2 := strconv.ParseFloat(s, 64)
	return err2 == nil
}
func parseKeyAsYAML(k string) (interface{}, bool) {
	// Try to parse k as YAML value
	var v interface{}
	// Use yaml.Unmarshal on the key string
	// Need to handle that yaml will treat "true" as bool, "123" as int, "[1,2]" as sequence, etc.
	if err := yaml.Unmarshal([]byte(k), &v); err != nil {
		return k, false
	}
	// If v is string and equals original k, then it's not complex
	if s, ok := v.(string); ok && s == k {
		// It's string, not complex, but should we treat numeric strings as complex? For "123", yaml will parse as int 123, not string, so v will be int, not string
		return k, false
	}
	// If v is nil (for "null"), return nil
	// For other types, return parsed value and indicate complex
	return v, true
}

func valueToYAMLNode(v interface{}, noConvert bool, inputFmt, outputFmt string) *yaml.Node {
	switch val := v.(type) {
	case *OrderedMap:
		node := &yaml.Node{Kind: yaml.MappingNode, Tag: "!!map"}
		for _, k := range val.Keys {
			// For nested map keys, not tryKeys here? We are already inside value
			keyNode := &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!str", Value: k}
			// Need to handle quoting similarly? For nested, keys like "b" are simple, so plain
			valNode := valueToYAMLNode(val.Values[k], noConvert, inputFmt, outputFmt)
			node.Content = append(node.Content, keyNode, valNode)
		}
		return node
	case map[string]interface{}:
		node := &yaml.Node{Kind: yaml.MappingNode, Tag: "!!map"}
		keys := make([]string, 0, len(val))
		for k := range val {
			keys = append(keys, k)
		}
		sort.Strings(keys)
		for _, k := range keys {
			keyNode := &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!str", Value: k}
			valNode := valueToYAMLNode(val[k], noConvert, inputFmt, outputFmt)
			node.Content = append(node.Content, keyNode, valNode)
		}
		return node
	case []interface{}:
		node := &yaml.Node{Kind: yaml.SequenceNode, Tag: "!!seq"}
		for _, elem := range val {
			node.Content = append(node.Content, valueToYAMLNode(elem, noConvert, inputFmt, outputFmt))
		}
		return node
	case string:
		// Check for inf strings to convert if needed?
		if !noConvert {
			if val == "Infinity" {
				return &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!float", Value: ".inf"}
			}
			if val == "-Infinity" {
				return &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!float", Value: "-.inf"}
			}
			if val == "NaN" {
				return &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!float", Value: ".nan"}
			}
		} else {
			// With noConvert, strings stay as strings, but for yaml output with noConvert, "Infinity" should stay as "Infinity" (quoted?).
			// How does yj encode "Infinity" string with -n? Observed: json {"a":"Infinity"} with -n to yaml gave "a: Infinity\n" (without dot, without quotes, plain)
			// That's ambiguous: "Infinity" without dot is plain string "Infinity", not float. So yaml will output plain "Infinity"
			// So for noConvert true, we should output string node with Value "Infinity" and tag str, not float.
			if val == "Infinity" {
				return &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!str", Value: "Infinity"}
			}
			if val == "-Infinity" {
				return &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!str", Value: "-Infinity"}
			}
			if val == "NaN" {
				return &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!str", Value: "NaN"}
			}
		}
		return &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!str", Value: val}
	case int:
		return &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!int", Value: strconv.FormatInt(int64(val), 10)}
	case int64:
		return &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!int", Value: strconv.FormatInt(val, 10)}
	case uint64:
		return &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!int", Value: strconv.FormatUint(val, 10)}
	case float64:
		// Handle inf/nan
		if isNaN(val) {
			return &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!float", Value: ".nan"}
		}
		if isInf(val, 1) {
			return &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!float", Value: ".inf"}
		}
		if isInf(val, -1) {
			return &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!float", Value: "-.inf"}
		}
		return &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!float", Value: strconv.FormatFloat(val, 'g', -1, 64)}
	case bool:
		if val {
			return &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!bool", Value: "true"}
		}
		return &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!bool", Value: "false"}
	case nil:
		return &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!null", Value: "null"}
	default:
		// Use reflect to handle other types
		rv := reflect.ValueOf(v)
		switch rv.Kind() {
		case reflect.Int, reflect.Int64, reflect.Int32:
			return &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!int", Value: fmt.Sprintf("%d", rv.Int())}
		case reflect.Float64:
			f := rv.Float()
			if isNaN(f) {
				return &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!float", Value: ".nan"}
			}
			if isInf(f, 1) {
				return &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!float", Value: ".inf"}
			}
			if isInf(f, -1) {
				return &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!float", Value: "-.inf"}
			}
			return &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!float", Value: strconv.FormatFloat(f, 'g', -1, 64)}
		default:
			return &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!str", Value: fmt.Sprintf("%v", v)}
		}
	}
}

func encodeTOML(v interface{}, indent bool, noConvert bool, isEmpty bool, inputFmt, outputFmt string) ([]byte, error) {
	if v == nil && isEmpty {
		return []byte{}, nil
	}
	// Handle OrderedMap
	if om, ok := v.(*OrderedMap); ok {
		if om.Len() == 0 {
			if isEmpty {
				return []byte{}, nil
			}
			// For json null to toml, om empty but should output "" (empty) as observed for null
			// For json {"a":null} -> toml '' (empty)
			// So if om is empty map, output empty
			return []byte{}, nil
		}
		// Check if v is nil top-level (panic case)
		// If v is nil and isEmpty false? But we already handled isEmpty.
		// For root nil (yaml "null" -> toml), should panic as observed
		// How to detect root nil? If v is nil and not isEmpty, then it's yaml "null" value
		// But our parseYAML for "null" returns nil, not OrderedMap. So that case is v==nil
		// For that, encodeTOML will be called with v==nil, not OrderedMap
	}
	if v == nil {
		// Panic case as observed: toml encoding of nil root panics
		// We should panic with same message
		// The panic message is "reflect: call of reflect.Value.Type on zero Value"
		// We can trigger panic by calling reflect.ValueOf(nil).Type()?
		// Let's just panic with that string
		panic("reflect: call of reflect.Value.Type on zero Value")
	}
	// For other cases, encode using toml
	// Need to handle OrderedMap conversion to something toml can encode preserving order
	// Toml encoder sorts keys, but we want to preserve order, so we need custom encoding that respects order and handles indent

	// Convert OrderedMap to a structure that toml can encode with order
	// We can use a map[string]interface{} but that loses order.
	// To preserve order, we need to encode manually or use a technique where we write TOML ourselves.

	// For simplicity, we will manually encode TOML preserving order, handling nested maps and indent

	if om, ok := v.(*OrderedMap); ok {
		return encodeOrderedMapTOML(om, indent, noConvert, inputFmt, outputFmt)
	}
	// For other types: slice, scalar, etc. Toml top-level must be map, but scalars and arrays at top-level are allowed? Observed yaml list to toml gave "[1, 2, 3]" etc.
	// For those, we can use toml.Marshal

	// For scalar at top-level, toml.Marshal will output the scalar without key? Example: yaml "123" -> toml "123" (observed)
	// Similarly json "123" -> toml "123"

	// For those, we can just use toml.Marshal

	var buf bytes.Buffer
	enc := toml.NewEncoder(&buf)
	if indent {
		enc.Indent = "  "
	} else {
		enc.Indent = ""
	}
	if err := enc.Encode(v); err != nil {
		return nil, err
	}
	return buf.Bytes(), nil
}

func encodeOrderedMapTOML(om *OrderedMap, indent bool, noConvert bool, inputFmt, outputFmt string) ([]byte, error) {
	// Manual TOML encoding preserving order
	// We need to handle:
	// - Keys with scalar values at top-level: "key = value"
	// - Keys with map values: need to create table "[key]" etc.
	// The toml library's encoding for nested maps uses tables.

	// Approach: Use toml.Marshal on a regular map but then reorder? Not easy.

	// Instead, we can try to use toml.NewEncoder with a custom ordered map that implements encoding via reflection with order preservation?
	// We can create a struct that holds ordered map and implements custom marshaling?

	// Simpler: Write our own TOML encoder that outputs in order, handling indent

	var buf bytes.Buffer
	indentStr := ""
	if indent {
		indentStr = "  "
	}
	// First, output scalar keys at top-level (and array scalar keys)
	// Collect keys that are scalar vs map
	var scalarKeys []string
	var tableKeys []string
	for _, k := range om.Keys {
		val := om.Values[k]
		switch val.(type) {
		case *OrderedMap, map[string]interface{}:
			tableKeys = append(tableKeys, k)
		default:
			// Check if val is string that should be converted to toml inf vs string?
			// For json "Infinity" string to toml with noConvert false, val is string "Infinity" but should be encoded as inf, not string
			// Our transformForTOML should have converted string "Infinity" to float Inf for toml output when not noConvert?
			// But currently parseJSON stored string "Infinity" as string, and we haven't transformed for toml output
			// So we need to handle transformation here
			scalarKeys = append(scalarKeys, k)
		}
	}
	// Output scalars first
	for i, k := range scalarKeys {
		val := om.Values[k]
		// Transform string inf to appropriate toml value
		val = transformForTOML(val, noConvert, inputFmt, outputFmt)
		// Skip nil values (toml omits null)
		if val == nil {
			continue
		}
		// Encode value to toml string
		valStr, err := tomlValueString(val)
		if err != nil {
			return nil, err
		}
		// Key quoting? Toml keys may need quoting if contain special chars? For now, use bare key
		// Observed: HCL keys are quoted, but Toml keys from yaml/json are bare? Example: "a" -> "a = 1"
		// For keys with spaces or special, toml may need quoted
		keyStr := tomlKeyString(k)
		buf.WriteString(fmt.Sprintf("%s = %s", keyStr, valStr))
		if i < len(scalarKeys)-1 || len(tableKeys) > 0 {
			buf.WriteString("\n")
		} else {
			buf.WriteString("\n")
		}
	}
	// Output tables
	for _, k := range tableKeys {
		val := om.Values[k]
		// Need to handle nested OrderedMap as table
		// For "[a]\n b =1" style, we need to output table header and then its content
		// Recursively encode

		// Determine if there are scalar keys already output, need blank line before tables?
		// Observed: "a = 1\n\n[b]\nc = 2\n" has blank line between scalar and table
		// For "a: { b: { c:1 } }" -> toml "[a]\n[a.b]\nc=1"
		// So we need to handle hierarchy

		// For simplicity, we will output each table with header

		// Use helper to encode table
		tableBytes, err := encodeTOMLTable(k, val, indent, noConvert, inputFmt, outputFmt, 0)
		if err != nil {
			return nil, err
		}
		// If there were scalar keys, ensure blank line before first table
		if len(scalarKeys) > 0 && k == tableKeys[0] {
			if buf.Len() > 0 && buf.Bytes()[buf.Len()-1] != '\n' {
				buf.WriteString("\n")
			}
			buf.WriteString("\n")
		} else if k != tableKeys[0] {
			buf.WriteString("\n")
		}
		buf.Write(tableBytes)
	}
	return buf.Bytes(), nil
}

func transformForTOML(v interface{}, noConvert bool, inputFmt, outputFmt string) interface{} {
	if s, ok := v.(string); ok && !noConvert {
		switch s {
		case "Infinity":
			return "+inf"
		case "-Infinity":
			return "-inf"
		case "NaN":
			return "nan"
		}
		// Actually for toml encoding, we want to return float inf, not string
		// The toml encoder will encode float inf as "inf" etc.
		// So convert string to float
		switch s {
		case "Infinity":
			return "+inf" // But toml library expects float64 Inf, not string
		}
	}
	// For now, handle string inf conversion to float
	if s, ok := v.(string); ok && !noConvert {
		switch s {
		case "Infinity":
			return "+inf" // placeholder, need actual float
		case "-Infinity":
			return "-inf"
		case "NaN":
			return "nan"
		}
	}
	return v
}
func tomlValueString(v interface{}) (string, error) {
	switch val := v.(type) {
	case string:
		// Need to quote string
		return strconv.Quote(val), nil
	case int:
		return strconv.FormatInt(int64(val), 10), nil
	case int64:
		return strconv.FormatInt(val, 10), nil
	case uint64:
		return strconv.FormatUint(val, 10), nil
	case float64:
		// Handle inf/nan? But these should have been converted to string already
		if isNaN(val) {
			return "nan", nil
		}
		if isInf(val, 1) {
			return "+inf", nil
		}
		if isInf(val, -1) {
			return "-inf", nil
		}
		return strconv.FormatFloat(val, 'f', -1, 64), nil
	case bool:
		if val {
			return "true", nil
		}
		return "false", nil
	case []interface{}:
		// Array
		var parts []string
		for _, elem := range val {
			s, err := tomlValueString(elem)
			if err != nil {
				return "", err
			}
			parts = append(parts, s)
		}
		return fmt.Sprintf("[%s]", strings.Join(parts, ", ")), nil
	case nil:
		// Toml has no null, so omit? But we already skip nil in caller
		return "", nil
	default:
		// Use reflection
		rv := reflect.ValueOf(v)
		switch rv.Kind() {
		case reflect.String:
			return strconv.Quote(rv.String()), nil
		case reflect.Int, reflect.Int64:
			return strconv.FormatInt(rv.Int(), 10), nil
		case reflect.Float64:
			f := rv.Float()
			if isNaN(f) {
				return "nan", nil
			}
			if isInf(f, 1) {
				return "+inf", nil
			}
			if isInf(f, -1) {
				return "-inf", nil
			}
			return strconv.FormatFloat(f, 'f', -1, 64), nil
		case reflect.Bool:
			if rv.Bool() {
				return "true", nil
			}
			return "false", nil
		default:
			return fmt.Sprintf("%v", v), nil
		}
	}
}
func tomlKeyString(k string) string {
	// Check if key needs quoting (contains special chars)
	// For simplicity, return k as is if it matches bare key regex
	// Bare keys: [A-Za-z0-9_-]
	if matched, _ := regexp.MatchString("^[A-Za-z0-9_-]+$", k); matched {
		return k
	}
	return strconv.Quote(k)
}
func encodeTOMLTable(key string, val interface{}, indent bool, noConvert bool, inputFmt, outputFmt string, depth int) ([]byte, error) {
	// For now, just handle OrderedMap
	var buf bytes.Buffer
	indentStr := ""
	if indent {
		indentStr = strings.Repeat("  ", depth)
	}
	// Header
	buf.WriteString(fmt.Sprintf("%s[%s]", indentStr, key))
	buf.WriteString("\n")
	// Content: if val is OrderedMap, iterate its keys
	if om, ok := val.(*OrderedMap); ok {
		for _, k := range om.Keys {
			subVal := om.Values[k]
			if subOM, ok := subVal.(*OrderedMap); ok {
				// Nested table: [key.subkey]
				// Recursively
				nestedKey := fmt.Sprintf("%s.%s", key, k)
				nestedBytes, err := encodeTOMLTable(nestedKey, subOM, indent, noConvert, inputFmt, outputFmt, depth)
				if err != nil {
					return nil, err
				}
				buf.Write(nestedBytes)
			} else {
				// Scalar
				valStr, _ := tomlValueString(subVal)
				if valStr == "" && subVal == nil {
					continue
				}
				keyStr := tomlKeyString(k)
				if indent {
					buf.WriteString(strings.Repeat("  ", depth+1))
				}
				buf.WriteString(fmt.Sprintf("%s = %s\n", keyStr, valStr))
			}
		}
	}
	return buf.Bytes(), nil
}

func encodeHCL(v interface{}, noConvert bool, isEmpty bool, inputFmt, outputFmt string) ([]byte, error) {
	if v == nil && isEmpty {
		return []byte{}, nil
	}
	if om, ok := v.(*OrderedMap); ok {
		if om.Len() == 0 {
			return []byte{}, nil
		}
		return encodeOrderedMapHCL(om, noConvert, inputFmt, outputFmt, 0)
	}
	// For other types: if top-level is not map, error? Observed: yaml list to hcl gave error
	// For scalar or list at top-level, HCL expects object, so error
	if _, ok := v.([]interface{}); ok {
		return nil, fmt.Errorf("Expected object, got unknown token: 1:1 LBRACK [")
	}
	// For scalar, also error
	if v != nil {
		// Check type
		switch v.(type) {
		case string:
			return nil, fmt.Errorf("Expected object, got unknown token: 1:1 STRING %q", v)
		case int, int64, float64:
			return nil, fmt.Errorf("Expected object, got unknown token: 1:1 NUMBER %v", v)
		case bool:
			return nil, fmt.Errorf("Expected object, got unknown token: 1:1 BOOL %v", v)
		case nil:
			return nil, fmt.Errorf("Expected object, got unknown token: 1:1 NULL null")
		}
	}
	return nil, fmt.Errorf("Expected object, got unknown token: 1:1 UNKNOWN")
}

func encodeOrderedMapHCL(om *OrderedMap, noConvert bool, inputFmt, outputFmt string, depth int) ([]byte, error) {
	var buf bytes.Buffer
	indentStr := strings.Repeat("  ", depth)
	for i, k := range om.Keys {
		val := om.Values[k]
		// Transform for HCL: handle inf strings? For yaml inf to hcl, default is string "Infinity", with -n is large float
		// Our parseYAML already handled noConvert, so val is either string or float
		// For HCL output, we need to encode accordingly

		// Key is quoted always as "\"key\" = value"
		keyStr := fmt.Sprintf("%q", k)
		var valStr string
		switch v := val.(type) {
		case *OrderedMap:
			// Object: "key" = {\n  "inner" = ...\n}
			innerBytes, err := encodeOrderedMapHCL(v, noConvert, inputFmt, outputFmt, depth+1)
			if err != nil {
				return nil, err
			}
			// Wrap inner
			valStr = fmt.Sprintf("{\n%s\n%s}", strings.TrimSpace(string(innerBytes)), indentStr)
			// Actually need to handle inner indent already
		case []interface{}:
			// Check if array of maps (like from HCL block) or array of scalars
			if len(v) > 0 {
				if _, ok := v[0].(*OrderedMap); ok {
					// List of objects: For HCL, each object becomes separate? Or single?
					// For json {"a":[{"b":1},{"c":2}]} -> hcl '"a" = {\n  "b" =1\n}\n\n"a" = {\n "c"=2\n}'
					// That's repeated keys. But for OrderedMap case, we have single key with list value
					// How to encode? If val is list of OrderedMaps, we need to output repeated attribute for each
					// For now, handle list of OrderedMaps as repeated
					// But our current loop is for each key, value is list. We need to handle that here
					// For key "a" with value [OM1, OM2], we should output two blocks: "a" = { ... } \n\n "a" = { ... }
					// So we need to special handle
					// Check if all elements are OrderedMap
					allOM := true
					for _, elem := range v {
						if _, ok := elem.(*OrderedMap); !ok {
							allOM = false
							break
						}
					}
					if allOM {
						// Output repeated
						for j, elem := range v {
							if j > 0 {
								buf.WriteString("\n\n")
							}
							omElem := elem.(*OrderedMap)
							innerBytes, _ := encodeOrderedMapHCL(omElem, noConvert, inputFmt, outputFmt, depth+1)
							innerStr := strings.TrimSpace(string(innerBytes))
							// For depth 0, key is quoted
							if depth == 0 {
								buf.WriteString(fmt.Sprintf("%s = {\n%s\n%s}", keyStr, innerStr, indentStr))
							} else {
								buf.WriteString(fmt.Sprintf("%s = {\n%s\n%s}", keyStr, innerStr, indentStr))
							}
						}
						continue
					}
				}
			}
			// Regular array
			valStrSlice := []string{}
			for _, elem := range v {
				s, _ := hclValueString(elem, noConvert, inputFmt, outputFmt)
				valStrSlice = append(valStrSlice, s)
			}
			valStr = fmt.Sprintf("[%s]", strings.Join(valStrSlice, ", "))
		case string:
			// Handle inf strings? For hcl, inf string should be quoted "Infinity" vs large number
			// If val is "Infinity" and noConvert false, keep as string quoted? But observed yaml .inf to hcl default is "\"a\" = \"Infinity\"" (quoted)
			// With -n, it's large number without quotes
			// So for string, quote
			valStr = strconv.Quote(v)
		case int, int64, uint64, float64, bool:
			s, _ := hclValueString(val, noConvert, inputFmt, outputFmt)
			valStr = s
		case nil:
			// HCL has no null, output empty?
			valStr = ""
		default:
			s, _ := hclValueString(val, noConvert, inputFmt, outputFmt)
			valStr = s
		}
		// If we already handled list of OMs, continue (already written)
		if _, ok := val.([]interface{}); ok {
			// Check if we already handled
			handled := false
			if arr, ok := val.([]interface{}); ok && len(arr) > 0 {
				if _, ok := arr[0].(*OrderedMap); ok {
					handled = true
				}
			}
			if handled {
				// Already written, need to add separator for next key?
				if i < len(om.Keys)-1 {
					buf.WriteString("\n\n")
				}
				continue
			}
		}
		// For normal case, write key = value
		if depth == 0 {
			// Top-level
			buf.WriteString(fmt.Sprintf("%s = %s", keyStr, valStr))
		} else {
			buf.WriteString(fmt.Sprintf("%s%s = %s", indentStr, keyStr, valStr))
		}
		if i < len(om.Keys)-1 {
			buf.WriteString("\n\n")
		}
	}
	return buf.Bytes(), nil
}

func hclValueString(v interface{}, noConvert bool, inputFmt, outputFmt string) (string, error) {
	switch val := v.(type) {
	case string:
		return strconv.Quote(val), nil
	case int:
		return strconv.Itoa(val), nil
	case int64:
		return strconv.FormatInt(val, 10), nil
	case uint64:
		return strconv.FormatUint(val, 10), nil
	case float64:
		if isNaN(val) {
			return "\"NaN\"", nil // But for hcl with noConvert false, NaN is string "NaN" quoted? Observed: yaml .nan to hcl default is "\"a\" = \"NaN\"" (quoted)
			// With -n, it's empty? Actually yaml .nan to hcl -n gave "\"a\" = " (empty)
		}
		if isInf(val, 1) {
			return strconv.FormatFloat(maxFloat, 'g', -1, 64), nil
		}
		if isInf(val, -1) {
			return strconv.FormatFloat(-maxFloat, 'g', -1, 64), nil
		}
		return strconv.FormatFloat(val, 'g', -1, 64), nil
	case bool:
		if val {
			return "true", nil
		}
		return "false", nil
	case nil:
		return "", nil
	default:
		return fmt.Sprintf("%v", val), nil
	}
}
