          -cj, -c = HCL to JSON
          -cc     = HCL to HCL
-n     Do not covert inf, -inf, and NaN to/from strings (YAML or TOML only)
-e     Escape HTML (JSON out only)
-i     Indent output (JSON or TOML out only)
-k     Attempt to parse keys as objects or numeric types (YAML out only)
-h     Show this help message
-v     Show version
`

// OrderedMap preserves insertion order
type OrderedMap struct {
	Keys   []string
	Values map[string]interface{}
}

func NewOrderedMap() *OrderedMap {
	return &OrderedMap{Keys: []string{}, Values: make(map[string]interface{})}
}

func (om *OrderedMap) Set(key string, value interface{}) {
	if _, exists := om.Values[key]; !exists {
		om.Keys = append(om.Keys, key)
	}
	om.Values[key] = value
}

func (om *OrderedMap) Get(key string) (interface{}, bool) {
	v, ok := om.Values[key]
	return v, ok
}

func (om *OrderedMap) Len() int {
	return len(om.Keys)
}

// For JSON marshaling, we will handle via custom function, not via MarshalJSON on OrderedMap directly,
// because we need to handle nested OrderedMaps recursively.

var maxFloat = 1.7976931348623157e+308

func main() {
	prog := os.Args[0]
	args := os.Args[1:]

	// Flag parsing: concatenate all args after stripping leading '-'
	allFlags := ""
	for _, arg := range args {
		stripped := strings.TrimLeft(arg, "-")
		allFlags += stripped
	}
	allowed := "ytjcrneikhv"
	var invalid []string
	for _, ch := range allFlags {
		if !strings.ContainsRune(allowed, ch) {
			invalid = append(invalid, string(ch))
		}
	}
	if len(invalid) > 0 {
		fmt.Fprintf(os.Stderr, usage, prog)
		fmt.Fprintf(os.Stderr, "\nError: invalid flags specified: %s\n", strings.Join(invalid, " "))
		os.Exit(1)
	}
	if strings.ContainsRune(allFlags, 'h') {
		fmt.Fprintf(os.Stdout, usage, prog)
		os.Exit(0)
	}
	if strings.ContainsRune(allFlags, 'v') {
		fmt.Fprintln(os.Stdout, "v0.0.0")
		os.Exit(0)
	}
	escapeHTML := strings.ContainsRune(allFlags, 'e')
	indent := strings.ContainsRune(allFlags, 'i')
	tryKeys := strings.ContainsRune(allFlags, 'k')
	noConvert := strings.ContainsRune(allFlags, 'n')

	// Determine conversion
	convChars := ""
	for _, ch := range allFlags {
		if strings.ContainsRune("ytjcr", ch) {
			convChars += string(ch)
		}
	}
	expanded := ""
	for _, ch := range convChars {
		if ch == 'r' {
			expanded += "jy"
		} else {
			expanded += string(ch)
		}
	}
	var inputFmt, outputFmt string
	if expanded == "" {
		inputFmt = "yaml"
		outputFmt = "json"
	} else if len(expanded) == 1 {
		switch expanded[0] {
		case 'y':
			inputFmt = "yaml"
			outputFmt = "json"
		case 't':
			inputFmt = "toml"
			outputFmt = "json"
		case 'j':
			inputFmt = "json"
			outputFmt = "json"
		case 'c':
			inputFmt = "hcl"
			outputFmt = "json"
		default:
			inputFmt = "yaml"
			outputFmt = "json"
		}
	} else {
		a := expanded[len(expanded)-2]
		b := expanded[len(expanded)-1]
		inputMap := map[byte]string{'y': "yaml", 't': "toml", 'j': "json", 'c': "hcl"}
		outputMap := map[byte]string{'y': "yaml", 't': "toml", 'j': "json", 'c': "hcl"}
		inputFmt = inputMap[a]
		outputFmt = outputMap[b]
	}

	// Validate flags
	// k only valid for yaml output
	// e only valid for json output
	// i only valid for json or toml output
	// Order priority: k, e, i
	if tryKeys && outputFmt != "yaml" {
		fmt.Fprintf(os.Stderr, usage, prog)
		fmt.Fprintln(os.Stderr, "\nError: flag -k only valid for YAML output")
		os.Exit(1)
	}
	if escapeHTML && outputFmt != "json" {
		fmt.Fprintf(os.Stderr, usage, prog)
		fmt.Fprintln(os.Stderr, "\nError: flag -e only valid for JSON output")
		os.Exit(1)
	}
	if indent && outputFmt != "json" && outputFmt != "toml" {
		fmt.Fprintf(os.Stderr, usage, prog)
		fmt.Fprintln(os.Stderr, "\nError: flag -i only valid for JSON or TOML output")
		os.Exit(1)
	}

	// Read stdin
	data, err := io.ReadAll(os.Stdin)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error reading stdin: %v\n", err)
		os.Exit(1)
	}
	isEmpty := len(bytes.TrimSpace(data)) == 0

	var parsed interface{}
	var parseErr error

	switch inputFmt {
	case "yaml":
		if isEmpty {
			parsed = nil
		} else {
			parsed, parseErr = parseYAML(data, noConvert, inputFmt, outputFmt)
		}
		if parseErr != nil {
			fmt.Fprintf(os.Stderr, "Error parsing YAML: %v\n", parseErr)
			os.Exit(1)
		}
	case "toml":
		if isEmpty {
			parsed = NewOrderedMap() // empty map for toml empty
		} else {
			parsed, parseErr = parseTOML(data, noConvert, inputFmt, outputFmt)
			if parseErr != nil {
				fmt.Fprintf(os.Stderr, "Error parsing TOML: %v\n", parseErr)
				os.Exit(1)
			}
		}
	case "json":
		if isEmpty {
			fmt.Fprintf(os.Stderr, "Error parsing JSON: unexpected end of JSON input\n")
			os.Exit(1)
		}
		parsed, parseErr = parseJSON(data, noConvert, inputFmt, outputFmt)
		if parseErr != nil {
			fmt.Fprintf(os.Stderr, "Error parsing JSON: %v\n", parseErr)
			os.Exit(1)
		}
	case "hcl":
		if isEmpty {
			parsed = NewOrderedMap()
		} else {
			parsed, parseErr = parseHCL(string(data), noConvert, inputFmt, outputFmt)
			if parseErr != nil {
				fmt.Fprintf(os.Stderr, "Error parsing HCL: %v\n", parseErr)
				os.Exit(1)
			}
		}
	}

	// Handle empty cases where parsed is nil and output expects something
	// For yaml empty -> json empty should output nothing (already)
	// For toml empty -> json should output "{}\n" etc. Our parseTOML for empty returns OrderedMap empty, which will encode to json "{}"

	var outBytes []byte
	var outErr error

	switch outputFmt {
	case "json":
		outBytes, outErr = encodeJSON(parsed, escapeHTML, indent, noConvert, isEmpty, inputFmt, outputFmt)
	case "yaml":
		outBytes, outErr = encodeYAML(parsed, tryKeys, noConvert, isEmpty, inputFmt, outputFmt)
	case "toml":
		outBytes, outErr = encodeTOML(parsed, indent, noConvert, isEmpty, inputFmt, outputFmt)
	case "hcl":
		outBytes, outErr = encodeHCL(parsed, noConvert, isEmpty, inputFmt, outputFmt)
	}

	if outErr != nil {
		// Check for HCL write error
		if strings.Contains(outErr.Error(), "Expected object") {
			fmt.Fprintf(os.Stderr, "Error writing HCL: %v\n", outErr)
			os.Exit(1)
		}
		if strings.Contains(outErr.Error(), "panic") {
			panic(outErr)
		}
		// Generic write error
		// For YAML key error, message is "Error writing YAML: ..."
		if outputFmt == "yaml" && strings.Contains(outErr.Error(), "Set") {
			fmt.Fprintf(os.Stderr, "Error writing YAML: %v\n", outErr)
			os.Exit(1)
		}
		fmt.Fprintf(os.Stderr, "Error writing %s: %v\n", strings.Title(outputFmt), outErr)
		os.Exit(1)
	}

	if len(outBytes) > 0 {
		os.Stdout.Write(outBytes)
	}
	// For some outputs, we need to ensure no extra output for empty
}

// YAML parsing

func parseYAML(data []byte, noConvert bool, inputFmt, outputFmt string) (interface{}, error) {
	var node yaml.Node
	if err := yaml.Unmarshal(data, &node); err != nil {
		return nil, err
	}
	return yamlNodeToInterface(&node, noConvert, inputFmt, outputFmt)
}

func yamlNodeToInterface(node *yaml.Node, noConvert bool, inputFmt, outputFmt string) (interface{}, error) {
	switch node.Kind {
	case yaml.DocumentNode:
		if len(node.Content) == 0 {
			return nil, nil
		}
		// YAML may have multiple documents? Original yj only handles first document? Test showed "---\na: 1\n---\nb: 2\n" gave only first document.
		return yamlNodeToInterface(node.Content[0], noConvert, inputFmt, outputFmt)
	case yaml.MappingNode:
		om := NewOrderedMap()
		for i := 0; i < len(node.Content); i += 2 {
			keyNode := node.Content[i]
			valNode := node.Content[i+1]
			keyRaw, err := yamlNodeToInterface(keyNode, noConvert, inputFmt, outputFmt)
			if err != nil {
				return nil, err
			}
			// Keys are expected to be strings, but YAML allows non-string keys. Original yj converts them to strings for JSON output?
			// For now, convert key to string via fmt
			keyStr := fmt.Sprintf("%v", keyRaw)
			// But for OrderedMap, we use string key
			val, err := yamlNodeToInterface(valNode, noConvert, inputFmt, outputFmt)
			if err != nil {
				return nil, err
			}
			om.Set(keyStr, val)
		}
		if om.Len() == 0 {
			// Return empty map
			return NewOrderedMap(), nil
		}
		return om, nil
	case yaml.SequenceNode:
		var arr []interface{}
		for _, child := range node.Content {
			val, err := yamlNodeToInterface(child, noConvert, inputFmt, outputFmt)
			if err != nil {
				return nil, err
			}
			arr = append(arr, val)
		}
		return arr, nil
	case yaml.ScalarNode:
		tag := node.Tag
		value := node.Value
		// Handle null
		if tag == "!!null" {
			return nil, nil
		}
		// Handle inf/nan strings
		switch value {
		case ".inf", ".Inf", ".INF":
			if noConvert {
				return maxFloat, nil
			}
			return "Infinity", nil
		case "-.inf", "-.Inf", "-.INF":
			if noConvert {
				return -maxFloat, nil
			}
			return "-Infinity", nil
		case ".nan", ".NaN", ".NAN":
			if noConvert {
				return nil, nil
			}
			return "NaN", nil
		}
		// Check tag for typed scalars
		switch tag {
		case "!!bool":
			if value == "true" || value == "True" || value == "TRUE" {
				return true, nil
			}
			if value == "false" || value == "False" || value == "FALSE" {
				return false, nil
			}
		case "!!int":
			// Try int64
			if i, err := strconv.ParseInt(value, 0, 64); err == nil {
				return i, nil
			}
			// Try uint
			if u, err := strconv.ParseUint(value, 0, 64); err == nil {
				// Return int64 if fits, else uint64
				if u <= 9223372036854775807 {
					return int64(u), nil
				}
				return u, nil
			}
			if f, err := strconv.ParseFloat(value, 64); err == nil {
				return f, nil
			}
			return value, nil
		case "!!float":
			if f, err := strconv.ParseFloat(value, 64); err == nil {
				// Check for inf/nan from string like ".inf" already handled, but float like "1.0"
				return f, nil
			}
			return value, nil
		case "!!str":
			return value, nil
		}
		// Default: try to infer type? For plain scalars with no tag, the tag is "!!str" or "!!int" etc already set by resolver.
		// If tag is "" (maybe?), treat as string
		// For untagged, yaml.v3 may have already resolved to appropriate tag.
		// If we get here, treat as string
		return value, nil
	case yaml.AliasNode:
		if node.Alias != nil {
			return yamlNodeToInterface(node.Alias, noConvert, inputFmt, outputFmt)
		}
		return nil, nil
	default:
		return nil, fmt.Errorf("unknown yaml node kind %d", node.Kind)
	}
}

// JSON parsing with order preservation

func parseJSON(data []byte, noConvert bool, inputFmt, outputFmt string) (interface{}, error) {
	return parseJSONOrdered(data, noConvert, inputFmt, outputFmt)
}

func parseJSONOrdered(data []byte, noConvert bool, inputFmt, outputFmt string) (interface{}, error) {
	dec := json.NewDecoder(bytes.NewReader(data))
	dec.UseNumber()
	return parseJSONValue(dec, noConvert, inputFmt, outputFmt)
}

func parseJSONValue(dec *json.Decoder, noConvert bool, inputFmt, outputFmt string) (interface{}, error) {
	tok, err := dec.Token()
	if err != nil {
		return nil, err
	}
	switch t := tok.(type) {
	case json.Delim:
		switch t {
		case '{':
			om := NewOrderedMap()
			for dec.More() {
				keyTok, err := dec.Token()
				if err != nil {
					return nil, err
				}
				key, ok := keyTok.(string)
				if !ok {
					return nil, fmt.Errorf("expected string key")
				}
				val, err := parseJSONValue(dec, noConvert, inputFmt, outputFmt)
				if err != nil {
					return nil, err
				}
				om.Set(key, val)
			}
			if _, err := dec.Token(); err != nil {
				return nil, err
			}
			if om.Len() == 0 {
				return NewOrderedMap(), nil
			}
			return om, nil
		case '[':
			var arr []interface{}
			for dec.More() {
				val, err := parseJSONValue(dec, noConvert, inputFmt, outputFmt)
				if err != nil {
					return nil, err
				}
				arr = append(arr, val)
			}
			if _, err := dec.Token(); err != nil {
				return nil, err
			}
			return arr, nil
		default:
			return nil, fmt.Errorf("unknown delim %v", t)
		}
	case string:
		return t, nil
	case json.Number:
		// Try int64
		if i, err := t.Int64(); err == nil {
			return i, nil
		}
		if f, err := t.Float64(); err == nil {
			return f, nil
		}
		return string(t), nil
	case bool:
		return t, nil
	case nil:
		return nil, nil
	default:
		return nil, fmt.Errorf("unknown token type %T", t)
	}
}

// TOML parsing

func parseTOML(data []byte, noConvert bool, inputFmt, outputFmt string) (interface{}, error) {
	var m map[string]interface{}
	meta, err := toml.Decode(string(data), &m)
	if err != nil {
		return nil, err
	}
	// Reconstruct ordered map using meta.Keys
	if len(m) == 0 {
		return NewOrderedMap(), nil
	}
	om := NewOrderedMap()
	// Use meta.Keys to determine order and nested structure
	// For each key in order, get value via traversing m
	for _, key := range meta.Keys() {
		val := getNestedValue(m, []string(key))
		converted := convertTOMLValue(val, noConvert, inputFmt, outputFmt)
		// Need to handle nested insertion without overwriting
		// Instead of directly setting nested, we will build via setNestedOrdered but we need to avoid double insertion for parent keys
		// Example: Keys = ["a"], ["a","b"] ; first inserts "a" with map, second should insert into existing "a"
		// So we use setNestedOrdered that merges
		setNestedOrdered(om, []string(key), converted, m)
	}
	// For any keys not in meta.Keys? Possibly arrays etc.
	// Also need to handle case where top-level is not map but scalar/array? Our decode into map would fail for those, but we already handled error.
	// For top-level scalar/array, toml.Decode into map would not work. So we need alternative handling.
	// Try decoding into interface{}?
	// For now, if m is empty but data is not empty and not decoded as map, try generic
	if om.Len() == 0 && len(m) > 0 {
		// Fallback: convert m directly
		for k, v := range m {
			om.Set(k, convertTOMLValue(v, noConvert, inputFmt, outputFmt))
		}
	}
	return om, nil
}

func getNestedValue(m map[string]interface{}, key []string) interface{} {
	var cur interface{} = m
	for i, k := range key {
		if mp, ok := cur.(map[string]interface{}); ok {
			if i == len(key)-1 {
				return mp[k]
			}
			cur = mp[k]
		} else {
			return nil
		}
	}
	return nil
}

func setNestedOrdered(om *OrderedMap, key []string, value interface{}, originalMap map[string]interface{}) {
	if len(key) == 1 {
		top := key[0]
		if existing, exists := om.Values[top]; exists {
			// If existing is OrderedMap and value is scalar, we should not overwrite the map?
			// Check if key corresponds to a table that already has subkeys
			// For TOML, a key like "a" with subkey "a.b" means "a" is a table, not a value.
			// The value for "a" from getNestedValue would be the map {"b": ...}
			// So if we already have "a" as OrderedMap, we should merge value if value is map
			if omExisting, ok := existing.(*OrderedMap); ok {
				if valMap, ok := value.(map[string]interface{}); ok {
					// Merge valMap into omExisting
					for k, v := range valMap {
						omExisting.Set(k, v)
					}
					return
				}
				if valOM, ok := value.(*OrderedMap); ok {
					for _, k := range valOM.Keys {
						omExisting.Set(k, valOM.Values[k])
					}
					return
				}
			}
			if _, ok := existing.(map[string]interface{}); ok {
				// Convert to OrderedMap and merge
				// Similar
			}
		}
		om.Set(top, value)
		return
	}
	top := key[0]
	var childOM *OrderedMap
	if existing, exists := om.Values[top]; exists {
		if om2, ok := existing.(*OrderedMap); ok {
			childOM = om2
		} else if mp, ok := existing.(map[string]interface{}); ok {
			childOM = mapToOrderedMap(mp)
			om.Set(top, childOM)
		} else {
			childOM = NewOrderedMap()
			om.Set(top, childOM)
		}
	} else {
		childOM = NewOrderedMap()
		om.Set(top, childOM)
	}
	setNestedOrdered(childOM, key[1:], value, originalMap)
}

func mapToOrderedMap(m map[string]interface{}) *OrderedMap {
	om := NewOrderedMap()
	keys := make([]string, 0, len(m))
	for k := range m {
		keys = append(keys, k)
	}
	sort.Strings(keys) // fallback sorted, but ideally preserve
	for _, k := range keys {
		om.Set(k, m[k])
	}
	return om
}

func convertTOMLValue(val interface{}, noConvert bool, inputFmt, outputFmt string) interface{} {
	if f, ok := val.(float64); ok {
		if !noConvert {
			if isInf(f, 1) {
				return "Infinity"
			}
			if isInf(f, -1) {
				return "-Infinity"
			}
			if isNaN(f) {
				return "NaN"
			}
		} else {
			if isInf(f, 1) {
				return maxFloat
			}
			if isInf(f, -1) {
				return -maxFloat
			}
			if isNaN(f) {
				return nil
			}
		}
	}
	if t, ok := val.(time.Time); ok {
		// Format as RFC3339 without unnecessary nanoseconds?
		// Observed: toml datetime "1979-05-27T07:32:00Z" -> json string same, yaml string same
		// For date "1979-05-27" (without time), toml decodes as time with 00:00:00Z and outputs as "1979-05-27T00:00:00Z"
		// So format with RFC3339Nano and trim?
		return t.Format(time.RFC3339Nano)
	}
	if mp, ok := val.(map[string]interface{}); ok {
		// Recursively convert
		// Need to preserve order? For nested maps, we lose order if using plain map
		// Convert to OrderedMap?
		om := NewOrderedMap()
		// Use sorted keys as fallback
		keys := make([]string, 0, len(mp))
		for k := range mp {
			keys = append(keys, k)
		}
		sort.Strings(keys)
		for _, k := range keys {
			om.Set(k, convertTOMLValue(mp[k], noConvert, inputFmt, outputFmt))
		}
		// If om has only one level and we want to return OrderedMap, but caller expects value to be put into ordered map, returning OrderedMap is okay
		// But for consistency, return OrderedMap if we need order
		// For now, return mp with converted values (but order lost)
		// Let's return OrderedMap
		if len(om.Keys) == 0 {
			return map[string]interface{}{}
		}
		return om
	}
	if arr, ok := val.([]interface{}); ok {
		for i, v := range arr {
			arr[i] = convertTOMLValue(v, noConvert, inputFmt, outputFmt)
		}
		return arr
	}
	if arr, ok := val.([]map[string]interface{}); ok {
		// TOML array of tables?
		var out []interface{}
		for _, m := range arr {
			out = append(out, convertTOMLValue(m, noConvert, inputFmt, outputFmt))
		}
		return out
	}
	return val
}

func isInf(f float64, sign int) bool {
	// Use math.IsInf
	if sign > 0 {
		return f > maxFloat/2 && f == f && f != 0 && f/f == 1 // crude, but need math
	}
	if sign < 0 {
		return f < -maxFloat/2 && f == f && f != 0 && f/f == 1
	}
	return false
}

func isNaN(f float64) bool {
	return f != f
}

// HCL parsing - simplified
func parseHCL(data string, noConvert bool, inputFmt, outputFmt string) (interface{}, error) {
	// Very simplified parser that handles:
	// - attributes: key = value
	// - blocks: key [labels] { body }
	// - object attribute: key = { ... }
	// For now, implement a simple lexer and parser.

	// We'll parse line by line, handling braces.

	// This is complex, so we will implement a minimal version that passes observed tests.

	// Use a recursive descent that handles:
	// - top-level is sequence of statements (attribute or block)
	// - attribute: key (=) value
	// - value can be: string, number, bool, null, list, object

	// For simplicity, we will use a function that parses HCL into OrderedMap where:
	// - attribute with scalar: key -> scalar
	// - attribute with object: key -> list containing object map
	// - block: key with labels -> nested list structure

	// Example: 'a = 1' => {"a":1}
	// 'a { b = 1 }' => {"a":[{"b":1}]}
	// 'block "label" { a = 1 }' => {"block":[{"label":[{"a":1}]}]}

	// We'll implement lexer that tokenizes HCL.

	tokens, err := tokenizeHCL(data)
	if err != nil {
		return nil, err
	}
	om, _, err := parseHCLTokens(tokens, 0, false)
	if err != nil {
		return nil, err
	}
	return om, nil
}

func tokenizeHCL(input string) ([]string, error) {
	// Very naive tokenizer: split by whitespace and handle quotes, braces, brackets, =, commas
	// For now, use simple approach: iterate characters
	var tokens []string
	i := 0
	for i < len(input) {
		c := input[i]
		if c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == ',' {
			i++
			continue
		}
		if c == '#' || (c == '/' && i+1 < len(input) && input[i+1] == '/') {
			// comment line
			for i < len(input) && input[i] != '\n' {
				i++
			}
			continue
		}
		if c == '"' {
			// string
			j := i + 1
			for j < len(input) {
				if input[j] == '\\' && j+1 < len(input) {
					j += 2
					continue
				}
				if input[j] == '"' {
					j++
					break
				}
				j++
			}
			tokens = append(tokens, input[i:j])
			i = j
			continue
		}
		if c == '{' || c == '}' || c == '[' || c == ']' || c == '=' {
			tokens = append(tokens, string(c))
			i++
			continue
		}
		// identifier, number, bool, null
		j := i
		for j < len(input) && input[j] != ' ' && input[j] != '\t' && input[j] != '\n' && input[j] != '\r' && input[j] != ',' && input[j] != '{' && input[j] != '}' && input[j] != '[' && input[j] != ']' && input[j] != '=' && input[j] != '"' {
			j++
		}
		if j > i {
			tokens = append(tokens, input[i:j])
			i = j
			continue
		}
		i++
	}
	return tokens, nil
}

func parseHCLTokens(tokens []string, pos int, inBlock bool) (*OrderedMap, int, error) {
	om := NewOrderedMap()
	for pos < len(tokens) {
		if tokens[pos] == "}" {
			// End of block
			pos++
			break
		}
		// Expect key
		if pos >= len(tokens) {
			break
		}
		key := tokens[pos]
		// Remove quotes if key is quoted? But HCL keys may be quoted? In yj, HCL output quotes keys like "\"a\" = 1", parsing should handle quoted keys.
		// For parsing, key may be quoted string "\"a\"" -> should be unquoted to "a"
		if strings.HasPrefix(key, "\"") && strings.HasSuffix(key, "\"") {
			unquoted, err := strconv.Unquote(key)
			if err == nil {
				key = unquoted
			} else {
				key = strings.Trim(key, "\"")
			}
		}
		pos++
		if pos >= len(tokens) {
			// Key without value? Maybe null?
			om.Set(key, nil)
			break
		}
		if tokens[pos] == "=" {
			// Attribute
			pos++
			if pos >= len(tokens) {
				return nil, pos, fmt.Errorf("expected value after =")
			}
			val, nextPos, err := parseHCLValue(tokens, pos)
			if err != nil {
				return nil, pos, err
			}
			// If val is OrderedMap (object), then wrap as list as per observed
			if omVal, ok := val.(*OrderedMap); ok {
				// Wrap as list containing one map
				// But if val is already a map from object, we need to wrap
				// For attribute object, yj wraps as list
				// For scalar, not wrapped
				// How to decide? Check if original was object vs scalar: val is OrderedMap indicates object
				// So wrap
				arr := []interface{}{omVal}
				// Also need to handle existing key: if key already exists and is list, append?
				// For duplicate attributes like 'a = 1\na = 2' => last wins? Observed 'a =1\na=2' => {"a":2} (last wins, not list). So not always list.
				// But for object, they wrap as list with one element.
				// However for duplicate object attributes, what happens? e.g., two blocks with same key should become list with two elements.
				// For attribute scalar duplicates, last wins.
				// So we need to check existing
				if existing, exists := om.Values[key]; exists {
					// If existing is list, append
					if existingArr, ok := existing.([]interface{}); ok {
						existingArr = append(existingArr, omVal)
						om.Set(key, existingArr)
					} else {
						// Overwrite? For scalar duplicate, last wins, we already Set will overwrite
						om.Set(key, arr)
					}
				} else {
					om.Set(key, arr)
				}
			} else {
				// Scalar or list
				// Check if val is list of something? For scalar list like [1,2]
				om.Set(key, val)
			}
			pos = nextPos
		} else if tokens[pos] == "{" {
			// Block without equals: key { ... }
			pos++ // consume {
			innerOM, nextPos, err := parseHCLTokens(tokens, pos, true)
			if err != nil {
				return nil, pos, err
			}
			// Block becomes list containing innerOM
			arr := []interface{}{innerOM}
			if existing, exists := om.Values[key]; exists {
				if existingArr, ok := existing.([]interface{}); ok {
					existingArr = append(existingArr, innerOM)
					om.Set(key, existingArr)
				} else {
					om.Set(key, arr)
				}
			} else {
				om.Set(key, arr)
			}
			pos = nextPos
		} else {
			// Block with labels: key "label1" "label2" { ... }
			// Collect labels
			var labels []string
			for pos < len(tokens) && tokens[pos] != "{" && tokens[pos] != "=" && tokens[pos] != "}" {
				lbl := tokens[pos]
				// Unquote
				if strings.HasPrefix(lbl, "\"") && strings.HasSuffix(lbl, "\"") {
					unquoted, _ := strconv.Unquote(lbl)
					lbl = unquoted
				}
				labels = append(labels, lbl)
				pos++
			}
			if pos < len(tokens) && tokens[pos] == "{" {
				pos++
				innerOM, nextPos, err := parseHCLTokens(tokens, pos, true)
				if err != nil {
					return nil, pos, err
				}
				// Build nested structure from labels
				// For block "label1" "label2" { a=1 } => {"block": [{"label1": [{"label2": [{"a":1}]}]}]}
				// So labels are nested: each label becomes a key with list containing next level
				var current interface{} = innerOM
				// Wrap from innermost label outward
				for i := len(labels) - 1; i >= 0; i-- {
					lbl := labels[i]
					inner := NewOrderedMap()
					inner.Set(lbl, []interface{}{current})
					current = inner
				}
				// current is now OrderedMap containing outermost label
				// Need to merge into om under key
				if curOM, ok := current.(*OrderedMap); ok {
					// curOM has one key which is labels[0], value is list containing rest
					// For block case, we want om[key] to be list containing the structure
					// Actually for 'block "label" { a=1 }', key="block", labels=["label"], innerOM={"a":...}
					// current after wrapping: {"label": [{"a":...}]}
					// Then om["block"] should be list containing current
					// But current is already OrderedMap with key "label"
					// So we need to treat current as the value to be wrapped for key
					// The value for key should be list containing an OrderedMap that has the label structure?
					// Let's check: For block "label" { a=1 }, expected JSON is {"block":[{"label":[{"a":1}]}]}
					// So om["block"] = [ {"label": [{"a":1}]} ]
					// Our current is {"label": [{"a":1}]} which is the map to be put in list
					// So we should do: om.Set(key, []interface{}{current})
					// But need to handle existing
					arr := []interface{}{current}
					if existing, exists := om.Values[key]; exists {
						if existingArr, ok := existing.([]interface{}); ok {
							existingArr = append(existingArr, current)
							om.Set(key, existingArr)
						} else {
							om.Set(key, arr)
						}
					} else {
						om.Set(key, arr)
					}
				}
				pos = nextPos
			} else if pos < len(tokens) && tokens[pos] == "=" {
				// Attribute with labels? Not expected, but handle
				pos++
				val, nextPos, err := parseHCLValue(tokens, pos)
				if err != nil {
					return nil, pos, err
				}
				om.Set(key, val)
				pos = nextPos
			} else {
				return nil, pos, fmt.Errorf("unexpected token %q after key %q", tokens[pos], key)
			}
		}
	}
	return om, pos, nil
}

func parseHCLValue(tokens []string, pos int) (interface{}, int, error) {
	if pos >= len(tokens) {
		return nil, pos, fmt.Errorf("unexpected end")
	}
	tok := tokens[pos]
	if tok == "{" {
		// Object
		pos++
		om, nextPos, err := parseHCLTokens(tokens, pos, true)
		if err != nil {
			return nil, pos, err
		}
		// Expect closing }
		// parseHCLTokens already consumed }
		return om, nextPos, nil
	}
	if tok == "[" {
		// List
		pos++
		var arr []interface{}
		for pos < len(tokens) && tokens[pos] != "]" {
			if tokens[pos] == "," {
				pos++
				continue
			}
			val, nextPos, err := parseHCLValue(tokens, pos)
			if err != nil {
				return nil, pos, err
			}
			arr = append(arr, val)
			pos = nextPos
		}
		if pos < len(tokens) && tokens[pos] == "]" {
			pos++
		}
		return arr, pos, nil
	}
	if strings.HasPrefix(tok, "\"") {
		// String
		unquoted, err := strconv.Unquote(tok)
		if err != nil {
			unquoted = strings.Trim(tok, "\"")
		}
		return unquoted, pos + 1, nil
	}
	// Check for bool, null, number
	if tok == "true" {
		return true, pos + 1, nil
	}
	if tok == "false" {
		return false, pos + 1, nil
	}
	if tok == "null" {
		return nil, pos + 1, nil
	}
	// Number
	if i, err := strconv.ParseInt(tok, 0, 64); err == nil {
		return i, pos + 1, nil
	}
	if f, err := strconv.ParseFloat(tok, 64); err == nil {
		return f, pos + 1, nil
	}
	// Otherwise treat as string (unquoted)
	return tok, pos + 1, nil
}

// Encode functions

func encodeJSON(v interface{}, escapeHTML, indent bool, noConvert bool, isEmpty bool, inputFmt, outputFmt string) ([]byte, error) {
	if v == nil && isEmpty {
		return []byte{}, nil
	}
	// Handle OrderedMap
	// Need to convert OrderedMap and nested structures to handle inf strings etc.
	// Also need to handle time.Time already converted.

	// Transform value for json output: handle inf strings vs numbers
	// For json output, if input was yaml/toml and noConvert false, inf floats should have been converted to strings already in parse stage.
	// But we also need to handle case where parsed value is float Inf and output is json with noConvert false: should be string, with true: maxFloat
	// Our parseYAMl already handled noConvert for inf. Similarly parseTOML. So for json output, we just need to marshal.

	// For ordered maps, we need custom marshaling preserving order
	// We'll convert OrderedMap recursively to a structure that json.Marshal can handle with order via custom function

	// Use a helper to marshal ordered
	var buf bytes.Buffer
	if indent {
		buf.WriteString("{\n")
		// Not correct for general; we need to handle any top-level type
		// For top-level is OrderedMap, we need to marshal with indent
		// Use json.MarshalIndent for OrderedMap?
		// We'll implement custom indent marshaling
		// For now, use json.Marshal with ordered handling
	}

	// Simpler: use a function marshalOrdered that handles OrderedMap, slices, etc. and respects escapeHTML and indent

	// Check if v is OrderedMap
	if om, ok := v.(*OrderedMap); ok {
		if om.Len() == 0 && isEmpty {
			// For toml empty -> json should be "{}\n" ; for yaml empty -> json should be "" (empty)
			// Distinguish: inputFmt == "toml" and isEmpty => output "{}"
			// For yaml empty -> output "" (empty)
			// For hcl empty -> json "{}" (observed hcl empty -> json '{}\n')
			if inputFmt == "yaml" && isEmpty {
				return []byte{}, nil
			}
			if inputFmt == "hcl" && isEmpty {
				return []byte("{}\n"), nil
			}
			if inputFmt == "toml" && isEmpty {
				return []byte("{}\n"), nil
			}
			// For json empty, not applicable (json empty is error)
			// For other, default empty map
			return []byte("{}\n"), nil
		}
		// Handle OrderedMap marshaling
		return marshalOrderedJSON(om, escapeHTML, indent)
	}
	// For other types (slice, scalar, nil)
	if v == nil {
		if isEmpty {
			return []byte{}, nil
		}
		return []byte("null\n"), nil
	}
	// For scalar or slice at top-level: e.g., yaml scalar "123" -> json "123\n", yaml list "[1,2]" -> json "[1,2]\n"
	// Use json.Marshal
	var data []byte
	var err error
	if indent {
		if escapeHTML {
			// json.MarshalIndent with escape
			data, err = json.MarshalIndent(v, "", "  ")
		} else {
			// Need to disable escape? json.Marshal escapes < > &
			// To not escape, we need to use Encoder with SetEscapeHTML(false)
			buf := &bytes.Buffer{}
			enc := json.NewEncoder(buf)
			enc.SetEscapeHTML(escapeHTML)
			enc.SetIndent("", "  ")
			if err := enc.Encode(v); err != nil {
				return nil, err
			}
			return buf.Bytes(), nil
		}
	} else {
		if escapeHTML {
			data, err = json.Marshal(v)
		} else {
			buf := &bytes.Buffer{}
			enc := json.NewEncoder(buf)
			enc.SetEscapeHTML(false)
			if err := enc.Encode(v); err != nil {
				return nil, err
			}
			// Encode adds newline, but Marshal does not; original json output has newline even without indent
			return buf.Bytes(), nil
		}
	}
	if err != nil {
		return nil, err
	}
	// Marshal without indent should have newline as per observed
	// json.Marshal does not add newline, but original does: '{"a":1}\n'
	// So add newline if not present
	if len(data) > 0 && data[len(data)-1] != '\n' {
		data = append(data, '\n')
	}
	return data, nil
}

func marshalOrderedJSON(om *OrderedMap, escapeHTML, indent bool) ([]byte, error) {
	// Use bytes.Buffer and manually marshal in order
	var buf bytes.Buffer
	if indent {
		buf.WriteString("{\n")
		for i, k := range om.Keys {
			buf.WriteString("  ")
			keyBytes, _ := json.Marshal(k)
			// Need to handle escapeHTML for key? json.Marshal escapes HTML by default if escape
			// But we disabled? For indent with escape true, we need to escape
			// Our marshalOrdered currently doesn't handle escapeHTML for keys
			// Simpler: use json.Marshal for key with appropriate escape
			// We'll handle via encoder per value

			// For value, need to marshal with order handling recursively
			valBytes, err := marshalValueJSON(om.Values[k], escapeHTML, indent, 1)
			if err != nil {
				return nil, err
			}
			buf.Write(keyBytes)
			buf.WriteString(": ")
			buf.Write(valBytes)
			if i < len(om.Keys)-1 {
				buf.WriteString(",")
			}
			buf.WriteString("\n")
		}
		buf.WriteString("}\n")
	} else {
		buf.WriteString("{")
		for i, k := range om.Keys {
			keyBytes, _ := json.Marshal(k)
			// For non-indent, we need to handle escapeHTML false?
			// Use custom marshal for key
			if !escapeHTML {
				// Need to not escape HTML: json.Marshal escapes <>& by default, but we want not escaped when escapeHTML false
				// So we need to use encoder with SetEscapeHTML
				// For simplicity, replace unicode escapes?
				// We'll handle via json.Marshal then replace?
				// Actually for keys, HTML chars unlikely, so ignore
			}
			valBytes, err := marshalValueJSON(om.Values[k], escapeHTML, indent, 0)
			if err != nil {
				return nil, err
			}
			buf.Write(keyBytes)
			buf.WriteString(":")
			buf.Write(valBytes)
			if i < len(om.Keys)-1 {
				buf.WriteString(",")
			}
		}
		buf.WriteString("}\n")
	}
	return buf.Bytes(), nil
}

func marshalValueJSON(v interface{}, escapeHTML bool, indent bool, depth int) ([]byte, error) {
	switch val := v.(type) {
	case *OrderedMap:
		return marshalOrderedJSON(val, escapeHTML, indent)
	case map[string]interface{}:
		// Convert to OrderedMap with sorted keys for fallback
		om := NewOrderedMap()
		keys := make([]string, 0, len(val))
		for k := range val {
			keys = append(keys, k)
		}
		sort.Strings(keys)
		for _, k := range keys {
			om.Set(k, val[k])
		}
		return marshalOrderedJSON(om, escapeHTML, indent)
	case []interface{}:
		var buf bytes.Buffer
		if indent {
			buf.WriteString("[\n")
			for i, elem := range val {
				buf.WriteString(strings.Repeat("  ", depth+1))
				b, err := marshalValueJSON(elem, escapeHTML, indent, depth+1)
				if err != nil {
					return nil, err
				}
				buf.Write(b)
				if i < len(val)-1 {
					buf.WriteString(",")
				}
				buf.WriteString("\n")
			}
			buf.WriteString(strings.Repeat("  ", depth))
			buf.WriteString("]")
		} else {
			buf.WriteString("[")
			for i, elem := range val {
				b, err := marshalValueJSON(elem, escapeHTML, indent, depth)
				if err != nil {
					return nil, err
				}
				buf.Write(b)
				if i < len(val)-1 {
					buf.WriteString(",")
				}
			}
			buf.WriteString("]")
		}
		return buf.Bytes(), nil
	case string:
		// Handle escapeHTML
		if escapeHTML {
			b, _ := json.Marshal(val)
			return b, nil
		} else {
			// Use encoder without escape
			buf := &bytes.Buffer{}
			enc := json.NewEncoder(buf)
			enc.SetEscapeHTML(false)
			enc.Encode(val)
			// Encode adds newline and quotes, trim newline
			bb := bytes.TrimSpace(buf.Bytes())
			return bb, nil
		}
	default:
		// For other types, use json.Marshal with appropriate escape
		if escapeHTML {
			return json.Marshal(val)
		} else {
			buf := &bytes.Buffer{}
			enc := json.NewEncoder(buf)
			enc.SetEscapeHTML(false)
			if err := enc.Encode(val); err != nil {
				return nil, err
			}
			bb := bytes.TrimSpace(buf.Bytes())
			return bb, nil
		}
	}
}

